1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Invoices feature: one place listing EVERY invoice across all projects, showing which project each
5	// one is for and what stage it is at. Read-only; owns its own state and talks to its own
6	// /api/all-invoices endpoint. data-testid anchors follow the spec's conventions.
7	type AllInvoice = {
8	  id: number;
9	  projectId: number;
10	  projectName: string;
11	  amount: number;
12	  status: string;
13	};
14	
15	function money(amount: number): string {
16	  return `$${Number(amount).toLocaleString('en-US', {
17	    minimumFractionDigits: 2,
18	    maximumFractionDigits: 2,
19	  })}`;
20	}
21	
22	// The stages an invoice can be at; 'ALL' leaves the list unfiltered.
23	const STATUSES = ['DRAFT', 'SENT', 'PAID'] as const;
24	
25	// One page of the all-invoices list as the /api/all-invoices endpoint serves it: the invoices on
26	// this page plus what the next/prev controls need (the 1-based page number and whether a page
27	// exists on either side).
28	type InvoicePage = {
29	  items: AllInvoice[];
30	  page: number;
31	  hasPrev: boolean;
32	  hasNext: boolean;
33	};
34	
35	function InvoicesPage() {
36	  const [invoices, setInvoices] = useState<AllInvoice[]>([]);
37	  const [status, setStatus] = useState<string>('ALL');
38	  // The list is shown a page at a time (10 per page); this is the 1-based page currently on screen.
39	  const [page, setPage] = useState(1);
40	  const [hasPrev, setHasPrev] = useState(false);
