66	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
67	// many, price each), the total worked out for you, and a form to add another line. Each line can be
68	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
69	// own line-item state, scoped to the one invoice it is showing.
70	function InvoiceDetail({
71	  invoiceId,
72	  onChange,
73	  onClose,
74	}: {
75	  invoiceId: number;
76	  onChange: () => void;
77	  onClose: () => void;
78	}) {
79	  const [items, setItems] = useState<EditItem[]>([]);
80	  const [description, setDescription] = useState('');
81	  const [qty, setQty] = useState('');
82	  const [unit, setUnit] = useState('');
83	  const [unitPrice, setUnitPrice] = useState('');
84	  const [payments, setPayments] = useState<Payment[]>([]);
