86	  const [paymentDate, setPaymentDate] = useState('');
87	  const [status, setStatus] = useState('');
88	  // The percentage discount taken off this invoice's subtotal (0 unless one is set).
89	  const [discountPct, setDiscountPct] = useState(0);
90	
91	  // The status is worked out from the payments recorded against the invoice, so re-read it whenever
92	  // a payment is added rather than flipping it by hand. The discount percentage comes back on the
93	  // same read.
94	  async function loadStatus() {
95	    const res = await fetch(`/api/invoices/${invoiceId}`);
96	    const inv: Invoice = await res.json();
97	    setStatus(inv.status);
98	    setDiscountPct(Number(inv.discountPct) || 0);
99	  }
100	
101	  async function load() {
102	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
103	    const rows: LineItem[] = await res.json();
104	    setItems(
105	      rows.map((li) => ({
