120	  async function submitPayment(e: React.FormEvent) {
121	    e.preventDefault();
122	    const value = Number(paymentAmount);
123	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
124	      return;
125	    }
126	    if (paymentDate.trim() === '') {
127	      return;
128	    }
129	    await fetch(`/api/invoices/${invoiceId}/payments`, {
130	      method: 'POST',
