160	  async function save(li: EditItem) {
161	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
162	      return;
163	    }
164	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
165	      method: 'POST',
166	      headers: { 'Content-Type': 'application/json' },
167	      body: JSON.stringify({
168	        description: li.description,
169	        qty: Number(li.qty),
170	        unit: li.unit,
171	        unitPrice: Number(li.unitPrice),
172	      }),
173	    });
174	    await load();
175	    onChange();
176	  }
177	
178	  async function remove(id: number) {
179	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
180	    await load();
181	    onChange();
182	  }
183	
184	  async function submit(e: React.FormEvent) {
185	    e.preventDefault();
