205	  }
206	
207	  // The subtotal is the sum of the line items; the discount is that percentage taken off it, and
208	  // the final total is the subtotal less the discount.
209	  const subtotal = items.reduce((sum, li) => sum + amountOf(li), 0);
210	  const discount = (subtotal * discountPct) / 100;
