329	// Which lifecycle actions an invoice offers depends on where it is in its lifecycle: a draft can be
330	// sent, a sent invoice can be marked paid. Collecting the mapping here keeps the row markup flat and
331	// gives one obvious place to add a new lifecycle action.
332	function InvoiceActions({
333	  invoice,
334	  onOpen,
335	  onSend,
336	  onPay,
337	  onCancel,
338	}: {
339	  invoice: Invoice;
340	  onOpen: () => void;
341	  onSend: () => void;
342	  onPay: () => void;
343	  onCancel: () => void;
344	}) {
