399	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
400	      setAmountError('Amount must be more than zero');
401	      return;
402	    }
403	    setAmountError('');
404	    await fetch('/api/invoices', {
405	      method: 'POST',
406	      headers: { 'Content-Type': 'application/json' },
407	      body: JSON.stringify({ projectId, amount: value }),
408	    });
409	    setAmount('');
410	    await load();
411	  }
412	
413	  // A lifecycle move (send, mark paid, …) is a POST to the matching action route followed by a reload;
414	  // routing them through one place means a new action is one more call site, not new plumbing.
415	  async function transition(id: number, action: 'send' | 'pay' | 'cancel') {
416	    await fetch(`/api/invoices/${id}/${action}`, { method: 'POST' });
417	    await load();
418	  }
419	
420	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
421	  const shownInvoices = sortByDue
422	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
423	    : invoices;
424	
425	  return (
426	    <>
427	      <form data-testid="invoice-form" onSubmit={submit}>
428	        <input
429	          data-testid="invoice-form-amount"
430	          placeholder="Amount"
431	          value={amount}
432	          onChange={(e) => setAmount(e.target.value)}
433	        />
434	        <button data-testid="invoice-form-submit" type="submit">
435	          Add invoice
436	        </button>
437	        {amountError && (
438	          <p data-testid="invoice-form-amount-error" role="alert">
439	            {amountError}
440	          </p>
441	        )}
442	      </form>
443	
444	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
445	        Sort by due date
446	      </button>
447	
448	      {openInvoiceId === null ? (
449	        <>
450	          <table data-testid="project-invoices-table">
451	            <tbody>
452	              {shownInvoices.map((inv) => (
453	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
454	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
455	                  <td data-testid="invoice-due-amount">{money(inv.amountDue)}</td>
456	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
457	                  <td data-testid="invoice-due">{inv.dueDate}</td>
458	                  <td data-testid="invoice-status">{inv.status}</td>
459	                  <td>
460	                    <InvoiceActions
461	                      invoice={inv}
462	                      onOpen={() => setOpenInvoiceId(inv.id)}
463	                      onSend={() => transition(inv.id, 'send')}
464	                      onPay={() => transition(inv.id, 'pay')}
465	                      onCancel={() => transition(inv.id, 'cancel')}
466	                    />
467	                  </td>
468	                </tr>
469	              ))}
470	            </tbody>
471	          </table>
472	
473	          <p data-testid="project-invoices-total">{money(total)}</p>
474	        </>
475	      ) : (
476	        <InvoiceDetail
477	          invoiceId={openInvoiceId}
478	          onChange={load}
479	          onClose={() => setOpenInvoiceId(null)}
480	        />
481	      )}
482	    </>
483	  );
484	}
